import type { Story } from './stories';

// The two decisions this room makes about a card, kept out of the component so
// they can be tested: what identifies a kept story, and how its score reads.

// A kept story is identified by BOTH its sentences. Never by position — the
// corpus is regenerated by `tools/build-horror.mjs` and a lower `--min-score`
// renumbers nothing at the head but everything after it, so an index-keyed
// favorite would drift onto a different story. Not by the setup alone either:
// three setups collide across the corpus, and one kept card lighting up
// another's star is the bug that would follow.
export const storyKey = (story: Pick<Story, 'setup' | 'turn'>): string =>
  `${story.setup}\n${story.turn}`;

// Reddit's own shorthand, because the number is furniture under the card and
// not a figure anybody reads exactly. One decimal through the thousands, whole
// beyond a hundred thousand — no score in the corpus comes near that, but a
// regenerated one should not suddenly grow a decimal place it has no room for.
export const compactScore = (score: number): string => {
  if (score < 1000) return String(score);
  if (score < 100000) return `${(score / 1000).toFixed(1)}k`;
  return `${Math.round(score / 1000)}k`;
};
